import {createHash} from 'node:crypto';import{createReadStream}from'node:fs';import{readFile,writeFile}from'node:fs/promises';import{performance}from'node:perf_hooks';import{isolatedQueryForRepository}from'/Users/xiyuanpan/prograph/dist/core/query/isolation.js';
const hash=async p=>{const h=createHash('sha256');for await(const x of createReadStream(p))h.update(x);return h.digest('hex');};
const normalize=x=>Array.isArray(x)?x.map(normalize):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).filter(([k])=>k!=='durationMs').map(([k,v])=>[k,normalize(v)])):x;
const cases=[['overview',[]],['architecture',[30]],['cycles',[]],['context',['semantic publication',{maxSymbols:50}]],['frameworkBindings',['tauri']],['filePage',[{limit:200}]],['diagnosticPage',[{limit:200}]],['searchSymbols',['prepareAuthorityMigration',20]]];
const corpora=[{repository:'/Users/xiyuanpan/prograph',index:'/private/tmp/prograph-authority-self-stable-20261018'},{repository:'/Users/xiyuanpan/Pastey',index:'/private/tmp/prograph-authority-pastey-20261018'}];const results=[];
for(const corpus of corpora){const file=corpus.index+'/semantic.sqlite',before=await hash(file),client=await isolatedQueryForRepository(corpus.repository,corpus.index);const methods=[];
 for(const[method,args]of cases){const samples=[];for(let i=0;i<20;i++){const started=performance.now();try{const value=await client[method](...args);const milliseconds=+(performance.now()-started).toFixed(3);const bytes=Buffer.byteLength(JSON.stringify(value)),resultHash=createHash('sha256').update(JSON.stringify(normalize(value))).digest('hex');samples.push({milliseconds,bytes,resultHash});}catch(e){samples.push({milliseconds:+(performance.now()-started).toFixed(3),error:String(e)});}}
 const times=samples.map(s=>s.milliseconds).sort((a,b)=>a-b);methods.push({method,args,samples,medianMs:(times[9]+times[10])/2,p95Ms:times[18],maxMs:times[19],errors:samples.filter(s=>s.error).length,distinctHashes:new Set(samples.filter(s=>s.resultHash).map(s=>s.resultHash)).size});process.stderr.write(corpus.repository+' '+method+': '+times[18]+'ms p95\n');}
 const after=await hash(file);if(before!==after)throw Error('Read-only corpus changed');results.push({...corpus,before,after,methods});}
const record={format:1,capturedAt:new Date().toISOString(),commit:'de4b5910da40a4b2b273c36ac6b5c5f5d1ed0dd9',scope:'Current default owned compatibility reads over previously validated real ProGraph/Pastey semantic snapshots. Source is not reindexed; existing stale notices remain honest. Each request uses the production isolated child executor and its existing admission/deadline/row/byte bounds.',methodology:'Twenty serial samples per method/repository; time includes fresh worker creation, SQLite opening, authority resolution, read/serialization and IPC. Source database SHA256 checked unchanged. OS cache not evicted; no concurrent local provider/test/benchmark jobs. Empirical nearest-rank p95 of 20 observations is not a portable SLO or tail distribution. Normalize only durationMs for result-hash stability. Native worker/compiler RSS unavailable; controller RSS is not substituted. No persistent pool or runtime code changes.',driverSha256:await hash('/private/tmp/prograph-authority-query-qualification.mjs'),implementationDigests:Object.fromEntries(await Promise.all(['query/isolation','query/query-worker','query/compatibility-global-read','semantic/compatibility-global','query/navigation'].map(async x=>[x,await hash('/Users/xiyuanpan/prograph/dist/core/'+x+'.js')]))),node:process.version,results};await writeFile('/private/tmp/prograph-authority-query-qualification.json',JSON.stringify(record,null,2)+'\n');if(results.some(r=>r.methods.some(m=>m.errors||m.distinctHashes!==1)))process.exitCode=1;
